/**
 * Toast.Viewport: the one viewport the application mounts, which draws every toast the store holds.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  TOAST_QUIET,
  actOnToastNotice,
  agentMember,
  announceToasts,
  claimSlot,
  createCell,
  createDerived,
  dismissToastNotice,
  elementRef,
  followToastFocus,
  getToasts,
  holdToastTimers,
  scope,
  subscribeToasts,
  toast,
  toastDetails,
  toastNotices,
  watchEffect,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import ToastCard from './ToastCard'
import type { ToasterMessages } from './Toast'

export interface ToastViewportProps {
  /**
   * The close button’s name, the announcement’s prefix and the region’s name, from the catalog.
   */
  messages?: ToasterMessages
}

/** Toast.Viewport: the one viewport the application mounts, which draws every toast the store holds. */
export default function ToastViewport(given: ToastViewportProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const list = elementRef<HTMLElement>()
    const region = elementRef<HTMLElement>()
    const version = createCell(0)
    const paused = createCell(false)
    const said = createCell(TOAST_QUIET)
    const say = createDerived(
      () =>
        props.messages ?? {
          dismiss: 'Dismiss',
          notification: 'Notification',
          viewport: 'Notifications (F8)',
        },
    )
    const records = createDerived(() => (version.value < 0 ? [] : getToasts()))
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran =
        ((version.value += 1),
        subscribeToasts(() => {
          version.value += 1
        }))
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const listener = ($event: KeyboardEvent) => {
        void ($event.key === 'F8' && ($event.preventDefault(), list.value?.focus()))
      }
      document.addEventListener('keydown', listener)
      release2 = () => document.removeEventListener('keydown', listener)
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = holdToastTimers(region.value, (held) => {
        paused.value = held
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = followToastFocus(list.value)
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    const effect5 = () => {
      said.value = announceToasts(said.value, records.value, list.value, say.value.notification)
    }
    watchEffect(
      createMemo(() => version.value),
      effect5,
      true,
    )
    let release6: (() => void) | undefined
    const effect6 = () => {
      release6?.()
      const ran = agentMember({
        member: 'Toast',
        element: () => region.value,
        state: () => ({ notices: toastNotices(getToasts()), details: toastDetails(getToasts()) }),
        actions: {
          dismiss: {
            argument: 'id',
            run: (value) => dismissToastNotice(toast, getToasts(), value),
          },
          act: { argument: 'id', run: (value) => actOnToastNotice(toast, getToasts(), value) },
        },
        withholds: () => [
          ...(list.value?.querySelectorAll('[data-member="toast"] > div ~ div') ?? []),
        ],
      })
      release6 = () => {
        ran()
      }
    }
    onMount(effect6)
    onCleanup(() => release6?.())
    return (
      <div role="region" aria-label={say.value.viewport} tabindex="-1" ref={region.attach}>
        {/* list */}
        <ol class={styles.viewport} tabindex="-1" data-toast-part="list" ref={list.attach}>
          <Each of={records.value} by={(record) => record.id} renew>
            {(record) => (
              <ToastCard record={record} dismissLabel={say.value.dismiss} paused={paused.value} />
            )}
          </Each>
        </ol>
        {/* polite */}
        <div class={a11y.visuallyHidden} role="status" aria-live="polite" aria-atomic="true">
          <Each of={[said.value.polite]} by={(saying) => saying.key} renew>
            {(saying) => <span>{saying.words}</span>}
          </Each>
        </div>
        {/* assertive */}
        <div class={a11y.visuallyHidden} role="alert" aria-live="assertive" aria-atomic="true">
          <Each of={[said.value.assertive]} by={(saying) => saying.key} renew>
            {(saying) => <span>{saying.words}</span>}
          </Each>
        </div>
      </div>
    )
  })
}
